package com.rhn.billing.application.reconciliation;

import com.rhn.billing.application.ReconciliationAdapterRegistry;
import com.rhn.billing.domain.*;
import com.rhn.billing.infrastructure.*;
import com.rhn.platform.dictionary.api.DictionaryBinding;
import com.rhn.shared.api.PageResult;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static com.rhn.billing.api.PaymentReconciliation.*;
import static com.rhn.shared.api.BusinessErrors.*;

@Service @Transactional(readOnly=true)
public class ReconciliationReadService {
 private final ReconciliationAttemptRepository attempts;private final ReconciliationAccess access;private final ReconciliationAdapterRegistry adapters;private final ReconciliationTaskService commands;
 private final ReconciliationTaskRepository tasks;private final ReconciliationBatchRepository batches;private final ReconciliationItemRepository items;
 private final ReconciliationStatementFileRepository files;private final ReconciliationStatementRowRepository rows;private final ReconciliationItemEventRepository events;
 public ReconciliationReadService(ReconciliationAttemptRepository attempts,ReconciliationAccess access,ReconciliationAdapterRegistry adapters,ReconciliationTaskService commands,ReconciliationTaskRepository tasks,ReconciliationBatchRepository batches,ReconciliationItemRepository items,ReconciliationStatementFileRepository files,ReconciliationStatementRowRepository rows,ReconciliationItemEventRepository events){this.attempts=attempts;this.access=access;this.adapters=adapters;this.commands=commands;this.tasks=tasks;this.batches=batches;this.items=items;this.files=files;this.rows=rows;this.events=events;}
 public PageResult<PaymentReconciliationTaskView> list(String method,LocalDate from,LocalDate to,String status,int page,int size){var c=access.require(READ);if(from==null||to==null||from.isAfter(to)||from.plusDays(366).isBefore(to))throw badRequest("RECON_RANGE_INVALID","查询日期范围不能超过一年");var scope=adapters.require(method).merchantScope(c.tenantId(),c.organizationId());if(status!=null&&!Set.of("QUEUED","RUNNING","WAITING_STATEMENT","RETRY_WAIT","COMPLETED","FAILED").contains(status))throw badRequest("RECON_STATUS_INVALID","任务状态筛选无效");return page(tasks.page(c.tenantId(),scope.fingerprint(),from,to,status,request(page,size)).map(this::task));}
 public PaymentReconciliationTaskView get(Long id){var c=access.require(READ);var t=tasks.findByIdAndTenantId(id,c.tenantId()).orElseThrow(()->notFound("RECON_TASK_NOT_FOUND","未找到对账任务"));commands.requireScope(t,c.tenantId(),c.organizationId());return task(t);}
 public PaymentReconciliationTaskDetail detail(Long id){var c=access.require(READ);var t=get(id);var versions=files.findByTenantIdAndTaskIdOrderByAttemptDesc(c.tenantId(),id).stream().map(f->new PaymentReconciliationFileView(f.id(),f.attempt(),f.sha256(),f.parserVersion(),f.createdAt(),f.proof(),Objects.equals(f.id(),t.latestFileId()),f.isComplete())).toList();var history=batches.findByTenantIdAndReconciliationTaskIdAndOrganizationIdOrderByExecutionNumberDesc(c.tenantId(),id,c.organizationId()).stream().map(this::batch).toList();return new PaymentReconciliationTaskDetail(t,versions,history,attempts.findTop50ByTenantIdAndTaskIdOrderByAttemptDesc(c.tenantId(),id).stream().map(a->new PaymentReconciliationAttemptView(a.attempt(),a.status(),a.startedAt(),a.finishedAt(),a.errorCode(),a.errorMessage(),a.fileId())).toList());}
 public PageResult<PaymentReconciliationItemView> items(Long batchId,boolean differences,int page,int size){var c=access.require(READ);var batch=requireBatch(batchId);return page(items.page(c.tenantId(),batch.id(),differences,request(page,size)).map(this::item));}
 public List<PaymentReconciliationEventView> events(Long itemId){var c=access.require(READ);var item=items.findById(itemId).filter(i->i.tenantId().equals(c.tenantId())).orElseThrow(()->notFound("RECON_ITEM_NOT_FOUND","未找到对账明细"));requireBatch(item.reconciliationBatchId());return events.findByTenantIdAndReconciliationItemIdOrderByOccurredAt(c.tenantId(),itemId).stream().map(e->new PaymentReconciliationEventView(e.eventType(),e.statusTo(),e.actorId(),e.reason(),e.occurredAt())).toList();}
 public PageResult<PaymentReconciliationUnallocatedView> unallocated(Long taskId,int page,int size){var c=access.require(READ);access.requireMerchant(c);var task=get(taskId);if(task.latestFileId()==null)return new PageResult<>(List.of(),0,0,page,size);return page(rows.findByTenantIdAndFileIdAndOrganizationIdIsNullOrderByLineNumber(c.tenantId(),task.latestFileId(),request(page,size)).map(r->new PaymentReconciliationUnallocatedView(r.id(),r.revision(),r.lineNumber(),r.transactionType(),r.merchantOrderNo(),r.refundRequestNo(),r.externalTransactionNo(),r.amount(),r.currencyCode(),r.channelStatus(),r.disposition(),r.reason(),r.proposerId())));}
 public ReconciliationBatch requireBatch(Long id){var c=access.require(READ);var b=batches.findByIdAndTenantId(id,c.tenantId()).orElseThrow(()->notFound("RECON_BATCH_NOT_FOUND","未找到对账批次"));access.batch(b,c);return b;}
 public PaymentReconciliationBatchView batch(ReconciliationBatch b){return new PaymentReconciliationBatchView(b.id(),b.revision(),b.batchNo(),b.executionNumber(),b.status().name(),b.closure(),b.localCount(),b.externalCount(),b.differenceCount(),b.localAmount(),b.externalAmount(),b.differenceAmount(),b.externalPayments(),b.acceptedRefunds(),b.finalRefunds(),b.fees(),b.currencyCode(),b.snapshotAt(),b.localSnapshotHash(),b.statementFileId());}
 private PaymentReconciliationTaskView task(ReconciliationTask t){var c=access.require(READ);var latest=t.latestFileId()==null?null:batches.findByTenantIdAndStatementFileIdAndOrganizationId(c.tenantId(),t.latestFileId(),c.organizationId()).orElse(null);boolean allocated=t.latestFileId()!=null&&rows.countUnresolvedUnallocated(c.tenantId(),t.latestFileId())==0;return new PaymentReconciliationTaskView(t.id(),t.revision(),t.paymentMethodCode(),t.businessDate(),t.currencyCode(),t.status(),t.attempt(),t.nextAttemptAt(),t.errorCode(),t.errorMessage(),t.latestFileId(),t.completedAt(),allocated,latest==null?null:batch(latest));}
 private PaymentReconciliationItemView item(ReconciliationItem i){var row=i.statementRowId()==null?null:rows.findByIdAndTenantId(i.statementRowId(),i.tenantId()).orElse(null);return new PaymentReconciliationItemView(i.id(),i.revision(),i.paymentOrderId(),i.paymentId(),i.statementRowId(),i.transactionType(),i.externalTransactionNo(),i.channelStatus(),i.matchType(),i.status(),i.localAmount(),i.externalAmount(),i.differenceAmount(),i.currencyCode(),i.channelOccurredAt(),i.localPostedAt(),i.resolvedBy(),i.resolution(),i.reviewerId(),row==null?null:row.merchantOrderNo(),row==null?null:row.refundRequestNo(),row==null?null:row.externalRefundNo());}
 private PageRequest request(int page,int size){if(page<0||size<1||size>100)throw badRequest("RECON_PAGE_INVALID","分页参数无效");return PageRequest.of(page,size);}
 private <T>PageResult<T> page(Page<T> p){return new PageResult<>(p.getContent(),p.getTotalElements(),p.getTotalPages(),p.getNumber(),p.getSize());}
 public record PaymentReconciliationTaskView(Long id,long revision,@DictionaryBinding("PAY_METHOD")String paymentMethodCode,LocalDate businessDate,String currencyCode,@DictionaryBinding("BIL_RECON_TASK_STATUS")String status,int attempt,Instant nextAttemptAt,String errorCode,String errorMessage,Long latestFileId,Instant completedAt,boolean merchantAllocationComplete,PaymentReconciliationBatchView latestBatch){}
 public record PaymentReconciliationTaskDetail(PaymentReconciliationTaskView task,List<PaymentReconciliationFileView> files,List<PaymentReconciliationBatchView> versions,List<PaymentReconciliationAttemptView> attempts){}
 public record PaymentReconciliationAttemptView(int attempt,@DictionaryBinding("BIL_RECON_TASK_STATUS")String status,Instant startedAt,Instant finishedAt,String errorCode,String errorMessage,Long fileId){}
 public record PaymentReconciliationFileView(Long id,int attempt,String sha256,String parserVersion,Instant createdAt,String proof,boolean latest,boolean validated){}
 public record PaymentReconciliationBatchView(Long id,long revision,String batchNo,int executionNumber,@DictionaryBinding("BIL_RECON_RESULT")String status,@DictionaryBinding("BIL_RECON_CLOSURE")String closure,int localCount,int externalCount,int differenceCount,BigDecimal localAmount,BigDecimal externalAmount,BigDecimal differenceAmount,BigDecimal externalPayments,BigDecimal acceptedRefunds,BigDecimal finalRefunds,BigDecimal fees,String currencyCode,Instant snapshotAt,String localSnapshotHash,Long statementFileId){}
 public record PaymentReconciliationItemView(Long id,long revision,Long paymentOrderId,Long paymentId,Long statementRowId,@DictionaryBinding("BIL_RECON_TXN_TYPE")String transactionType,String externalTransactionNo,@DictionaryBinding("BIL_RECON_CHANNEL_STATUS")String channelStatus,@DictionaryBinding("BIL_RECON_MATCH_TYPE")String comparisonResult,@DictionaryBinding("BIL_RECON_DISPOSITION")String status,BigDecimal localAmount,BigDecimal externalAmount,BigDecimal differenceAmount,String currencyCode,Instant channelOccurredAt,Instant localPostedAt,Long proposedBy,String resolution,Long reviewedBy,String merchantOrderNo,String refundRequestNo,String externalRefundNo){}
 public record PaymentReconciliationEventView(@DictionaryBinding("BIL_RECON_EVENT_TYPE")String eventType,@DictionaryBinding("BIL_RECON_DISPOSITION")String statusTo,Long actorId,String reason,Instant occurredAt){}
 public record PaymentReconciliationUnallocatedView(Long id,long revision,int lineNumber,@DictionaryBinding("BIL_RECON_TXN_TYPE")String transactionType,String merchantOrderNo,String refundRequestNo,String externalTransactionNo,BigDecimal amount,String currencyCode,@DictionaryBinding("BIL_RECON_CHANNEL_STATUS")String channelStatus,@DictionaryBinding("BIL_RECON_DISPOSITION")String status,String reason,Long proposedBy){}
}
